"""Summarise saved render measurements only."""
import csv,json
from pathlib import Path
import numpy as np
ROOT=Path.cwd();OUT=ROOT/'reports/stage1'
def aggregate(labels):
 reports=[json.loads((OUT/(l+'.json')).read_text()) for l in labels];frames=[]
 for label in labels:
  rows=csv.DictReader(next((OUT/'raw'/label).glob('frames-*.csv')).open())
  frames += [float(r['wall_frame_interval_ms']) for r in rows if float(r['wall_seconds'])>=5]
 a=np.array(frames);return {'frames':len(a),'fps':float(1000/a.mean()),'mean_ms':float(a.mean()),'p95_ms':float(np.percentile(a,95)),'p99_ms':float(np.percentile(a,99)),'max_ms':float(a.max()),'cpu_one_core_mean_percent':float(np.mean([r['native_cpu_one_core_percent']['mean'] for r in reports])),'host_cpu_mean_percent':float(np.mean([r['host_cpu_percent']['mean'] for r in reports])),'native_rss_sampled_peak_mb':max(r['native_rss_bytes']['max'] for r in reports)/1e6,'gpu_device_mean_percent':float(np.mean([r['gpu_device_busy_percent']['mean'] for r in reports])),'packed_each':[r['run']['packed'] for r in reports],'sim_time_each':[r['run']['sim_time'] for r in reports]}
before=aggregate(['before-1','before-2']);after=aggregate(['after-final-1','after-final-2']);report={'before':before,'after':after,'measured_source':'18d1692','method':'Two35s runs per version, first5s frames excluded. Same1600x900, original fixed overview transform/viewport, cap60/VSync0,4MSAA, seed42 healthy1x, PLC profile. Unrelated applications preserved; original inspection service PID41095 remained alive. No inference in timed runs.','limits':'Short rendering comparison on this host only. Resource warm-up uses5s from process launch; frame warm-up uses Unity wall time. GPU counter is whole device; RSS is resident process accounting; no overlapping memory sum. Production sizing/unrelated host comparison unproven.'}
(OUT/'performance-summary.json').write_text(json.dumps(report,indent=2))
lines=['# Stage 1 rendering comparison','','Measured native source18d1692, Unity6000.6.5f1 Linux Mono release, Built-in / Standard / OpenGLCore. A395 Ryzen AI Max+395, Radeon8060S, Ubuntu24.04.5.1600×900,4MSAA,VSync0,target60. Healthy seed42/1×/PLC profile; same original overview transform and full viewport held by --comparison-camera. The customer default view now reserves room for the HUD and uses a separate presentation composition; this table is the controlled common view, not a benchmark of every close-up.','','Two35-second runs per version, excluding first5seconds of frame intervals. Early after runs are retained as checkpoints, not added to the final sample. Frames use Unity unscaled wall intervals from Awake; resource samples use monotonic process-launch time with first5seconds excluded. Simulated timestamps are distinct.','','| Metric | Before | Stage 1 |','|---|---:|---:|']
for key,label,suffix in [('fps','Mean FPS',''),('mean_ms','Mean frame',' ms'),('p95_ms','Frame p95',' ms'),('p99_ms','Frame p99',' ms'),('max_ms','Worst frame',' ms'),('cpu_one_core_mean_percent','Native CPU (one core =100%)','%'),('host_cpu_mean_percent','Host CPU (32 logical CPU capacity)','%'),('native_rss_sampled_peak_mb','Native sampled peak RSS',' MB'),('gpu_device_mean_percent','Device-wide GPU busy','%')]:lines.append(f"| {label} | {before[key]:.3f}{suffix} | {after[key]:.3f}{suffix} |")
lines += ['','Both versions packed44 bottles at simulated74.75s in each run, with zero rejects. No material60FPS regression observed in this short test. CPU and resident memory increased due to the extra presentation geometry/materials. This is not a measured inference workload benchmark.','','GPU busy is directly measured sysfs device occupancy including desktop/background work; no per-process percentage attribution or claimed GPU optimisation. Host memory, DRM accounting and process RSS overlap and are never added. Background service states were held: original inspection service active throughout; prior/native/streaming units inactive as found. Read-only Ollama residency polling is not inference. No Qwen/Gemma call, model reload, driver/backend change or budget reset.','','Raw frame CSVs, resource samples, run configuration and logs: reports/stage1/raw/{before-1,before-2,after-final-1,after-final-2}; summaries: reports/stage1/performance-summary.json and corresponding JSON/PNG files. Raw data remains local, excluded from public source delivery. No hardware necessity/superiority or broader workload claim.']
(ROOT/'presentation/PERFORMANCE.md').write_text('\n'.join(lines)+'\n');print(json.dumps(report,indent=2))
